package com.asmj.marketplace.emergency;

import com.asmj.marketplace.masterdata.MasterDataOption;
import com.asmj.marketplace.approval.ApprovalCase;
import com.asmj.marketplace.approval.ApprovalCaseRepository;
import com.asmj.marketplace.approval.ApprovalEntry;
import com.asmj.marketplace.masterdata.MasterDataOptionRepository;
import com.asmj.marketplace.model.Role;
import com.asmj.marketplace.model.UserAccount;
import com.asmj.marketplace.notification.NotificationService;
import com.asmj.marketplace.repository.UserAccountRepository;
import com.asmj.marketplace.service.CloudinaryImageService;
import java.security.Principal;
import java.time.Instant;
import java.util.*;
import java.util.stream.Collectors;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;

@Controller
public class EmergencyServicesController {
 private final EmergencyProviderRepository providers; private final EmergencyAssistanceRequestRepository requests; private final MasterDataOptionRepository master; private final UserAccountRepository users; private final CloudinaryImageService uploads; private final NotificationService notifications; private final ApprovalCaseRepository approvalCases;
 public EmergencyServicesController(EmergencyProviderRepository p,EmergencyAssistanceRequestRepository r,MasterDataOptionRepository m,UserAccountRepository u,CloudinaryImageService up,NotificationService n,ApprovalCaseRepository ac){providers=p;requests=r;master=m;users=u;uploads=up;notifications=n;approvalCases=ac;}
 private UserAccount user(Principal p){return users.findByEmailIgnoreCase(p.getName()).orElseThrow();}
 private List<MasterDataOption> options(String group){return master.findByGroupKeyAndActiveTrueOrderBySortOrderAscLabelAsc(group);}
 private String label(String group,String code){return master.findByGroupKeyAndCode(group,code).filter(MasterDataOption::isActive).map(MasterDataOption::getLabel).orElseThrow(()->new IllegalArgumentException("Select a valid "+group.toLowerCase(Locale.ROOT).replace('_',' ')+"."));}
 @ModelAttribute("emergencyCategories") public List<MasterDataOption> categories(){return options("EMERGENCY_CATEGORY");}
 @GetMapping("/emergency") public String directory(@RequestParam(required=false) String category,@RequestParam(required=false) String pincode,@RequestParam(required=false) String state,Model m){List<EmergencyProvider> list=providers.findByStatusOrderByProviderNameAsc("APPROVED").stream().filter(p->category==null||category.isBlank()||category.equals(p.getCategoryCode())).filter(p->pincode==null||pincode.isBlank()||pincode.equals(p.getPincode())||(p.getServicePincodes()!=null&&p.getServicePincodes().contains(pincode))).filter(p->state==null||state.isBlank()||state.equals(p.getStateCode())).toList();m.addAttribute("providers",list);m.addAttribute("selectedCategory",category);m.addAttribute("selectedPincode",pincode);m.addAttribute("selectedState",state);return "emergency/directory";}
 @GetMapping("/emergency/providers/register") public String register(Model m,Principal p){UserAccount u=user(p);if(u.getRole()!=Role.ROLE_VENDOR)return "auth/access-denied";m.addAttribute("provider",providers.findByOwnerUserIdOrderByUpdatedAtDesc(u.getId()).stream().findFirst().orElseGet(EmergencyProvider::new));m.addAttribute("states",options("INDIA_STATE"));return "emergency/provider-form";}
 @PostMapping("/emergency/providers/register") public String saveProvider(@ModelAttribute EmergencyProvider form,@RequestParam(required=false) List<MultipartFile> documents,@RequestParam(required=false) List<String> documentTypes,Principal p,RedirectAttributes ra){UserAccount u=user(p);if(u.getRole()!=Role.ROLE_VENDOR)return "auth/access-denied";try{
  if(blank(form.getProviderName())||blank(form.getPhone())||blank(form.getCategoryCode())||blank(form.getStateCode())||blank(form.getCityCode())||!digits(form.getPincode(),6))throw new IllegalArgumentException("Complete provider name, phone, category and valid State, City and 6-digit PIN code.");
  form.setCategoryLabel(label("EMERGENCY_CATEGORY",form.getCategoryCode()));if(!blank(form.getSubcategoryCode()))form.setSubcategoryLabel(label("EMERGENCY_SUBCATEGORY",form.getSubcategoryCode()));form.setStateLabel(label("INDIA_STATE",form.getStateCode()));form.setCityLabel(label("INDIA_CITY",form.getCityCode()));
  MasterDataOption city=master.findByGroupKeyAndCode("INDIA_CITY",form.getCityCode()).orElseThrow();if(!Objects.equals(city.getParentCode(),form.getStateCode()))throw new IllegalArgumentException("Selected city does not belong to the selected State.");
  if(!blank(form.getPincode())){boolean pinExists=master.findByGroupKeyAndCode("INDIA_PINCODE",form.getPincode()).filter(MasterDataOption::isActive).filter(x->Objects.equals(x.getParentCode(),form.getCityCode())).isPresent();if(!pinExists)throw new IllegalArgumentException("Select a PIN code configured for the selected City in Master Data Management.");}
  EmergencyProvider saved=providers.findByOwnerUserIdOrderByUpdatedAtDesc(u.getId()).stream().filter(x->!"REJECTED".equals(x.getStatus())).findFirst().orElse(form);saved.setOwnerUserId(u.getId());saved.setOwnerEmail(u.getEmail());saved.setProviderName(form.getProviderName().trim());saved.setProviderType(form.getProviderType());saved.setContactPerson(form.getContactPerson());saved.setPhone(form.getPhone().trim());saved.setAlternatePhone(form.getAlternatePhone());saved.setEmail(blank(form.getEmail())?u.getEmail():form.getEmail());saved.setDescription(form.getDescription());saved.setCategoryCode(form.getCategoryCode());saved.setCategoryLabel(form.getCategoryLabel());saved.setSubcategoryCode(form.getSubcategoryCode());saved.setSubcategoryLabel(form.getSubcategoryLabel());saved.setStateCode(form.getStateCode());saved.setStateLabel(form.getStateLabel());saved.setCityCode(form.getCityCode());saved.setCityLabel(form.getCityLabel());saved.setPincode(form.getPincode());saved.setServicePincodes(form.getServicePincodes()==null?new ArrayList<>():form.getServicePincodes().stream().filter(x->digits(x,6)).distinct().toList());saved.setOperatingHours(form.getOperatingHours());saved.setAvailable24x7(form.isAvailable24x7());saved.setAvailability("AVAILABLE".equals(form.getAvailability())||"BUSY".equals(form.getAvailability())?form.getAvailability():"UNAVAILABLE");saved.setCharges(form.getCharges());saved.setUpdatedAt(Instant.now());
  if(documents!=null)for(int i=0;i<documents.size();i++){MultipartFile f=documents.get(i);if(f!=null&&!f.isEmpty()){Map<String,Object> uploaded=uploads.uploadDocument(f,"asmj-marketplace/emergency/providers/"+u.getId());saved.getDocuments().add(new EmergencyProvider.EmergencyDocument(documentTypes!=null&&i<documentTypes.size()?documentTypes.get(i):"SUPPORTING_DOCUMENT",f.getOriginalFilename(),String.valueOf(uploaded.get("secure_url"))));}}
  if(saved.getId()==null)saved.setCreatedAt(Instant.now());saved.setStatus("PENDING_APPROVAL");saved.setAdminNote(null);providers.save(saved);
  boolean activeCase=approvalCases.findByOwnerUserIdOrderByUpdatedAtDesc(u.getId()).stream().anyMatch(c->"EMERGENCY_PROVIDER".equals(c.getModule())&&saved.getId().equals(c.getSubjectId())&&!List.of("APPROVED","REJECTED").contains(c.getStatus()));
  if(!activeCase){ApprovalCase ac=new ApprovalCase();ac.setOwnerUserId(u.getId());ac.setOwnerEmail(u.getEmail());ac.setModule("EMERGENCY_PROVIDER");ac.setSubjectType("EmergencyProvider");ac.setSubjectId(saved.getId());ac.setSubjectTitle(saved.getProviderName());ac.setStatus("SUBMITTED");ac.setSubmittedAt(Instant.now());ac.setUpdatedAt(Instant.now());ac.getHistory().add(new ApprovalEntry(u.getEmail(),u.getRole().name(),"SUBMITTED_FOR_APPROVAL","Emergency provider profile and verification documents submitted."));approvalCases.save(ac);notifications.notifyAdmins("New emergency provider approval request",saved.getProviderName()+" submitted an emergency provider profile for review.","APPROVAL",ac.getId());}
  ra.addFlashAttribute("successMessage","Provider profile submitted to the Approval Centre. It will appear in the public directory only after Admin approval.");return "redirect:/emergency/providers/register";
 }catch(IllegalArgumentException|IllegalStateException ex){ra.addFlashAttribute("errorMessage",ex.getMessage());return "redirect:/emergency/providers/register";}}
 @GetMapping("/emergency/requests/new") public String requestForm(Model m){m.addAttribute("states",options("INDIA_STATE"));return "emergency/request-form";}
 @PostMapping("/emergency/requests") public String createRequest(@RequestParam String categoryCode,@RequestParam(required=false) String subcategoryCode,@RequestParam String stateCode,@RequestParam String cityCode,@RequestParam String pincode,@RequestParam String address,@RequestParam String description,@RequestParam String customerPhone,Principal p,RedirectAttributes ra){UserAccount u=user(p);if(u.getRole()!=Role.ROLE_CUSTOMER)return "auth/access-denied";try{if(!digits(pincode,6)||blank(address)||blank(description)||blank(customerPhone))throw new IllegalArgumentException("Enter a valid 6-digit PIN code, address, description and contact phone.");String cat=label("EMERGENCY_CATEGORY",categoryCode),st=label("INDIA_STATE",stateCode),ct=label("INDIA_CITY",cityCode);MasterDataOption city=master.findByGroupKeyAndCode("INDIA_CITY",cityCode).orElseThrow();if(!Objects.equals(city.getParentCode(),stateCode))throw new IllegalArgumentException("Selected City does not belong to selected State.");if(master.findByGroupKeyAndCode("INDIA_PINCODE",pincode).filter(MasterDataOption::isActive).filter(x->Objects.equals(x.getParentCode(),cityCode)).isEmpty())throw new IllegalArgumentException("PIN code is not configured for the selected City.");EmergencyAssistanceRequest r=new EmergencyAssistanceRequest();r.setCustomerUserId(u.getId());r.setCustomerName(u.getFullName());r.setCustomerPhone(customerPhone);r.setCategoryCode(categoryCode);r.setCategoryLabel(cat);r.setSubcategoryCode(subcategoryCode);if(!blank(subcategoryCode))r.setSubcategoryLabel(label("EMERGENCY_SUBCATEGORY",subcategoryCode));r.setStateCode(stateCode);r.setStateLabel(st);r.setCityCode(cityCode);r.setCityLabel(ct);r.setPincode(pincode);r.setAddress(address);r.setDescription(description);r.setPreferredContact(customerPhone);requests.save(r);
  List<EmergencyProvider> eligible=providers.findByStatusAndAvailabilityOrderByProviderNameAsc("APPROVED","AVAILABLE").stream().filter(x->categoryCode.equals(x.getCategoryCode())).filter(x->pincode.equals(x.getPincode())||(x.getServicePincodes()!=null&&x.getServicePincodes().contains(pincode))).toList();for(EmergencyProvider ep:eligible)notifications.notifyUser(ep.getOwnerUserId(),"New emergency assistance request","A customer requested "+cat+" assistance in "+ct+". Open your emergency provider requests to review.","EMERGENCY_REQUEST",r.getId());ra.addFlashAttribute("successMessage","Your request was recorded. "+eligible.size()+" matching available provider(s) were notified. A response is not guaranteed; for immediate danger or medical emergency in India, call 112 directly.");return "redirect:/emergency/requests/mine";
 }catch(IllegalArgumentException ex){ra.addFlashAttribute("errorMessage",ex.getMessage());return "redirect:/emergency/requests/new";}}
 @GetMapping("/emergency/requests/mine") public String mine(Principal p,Model m){UserAccount u=user(p);m.addAttribute("requests",requests.findByCustomerUserIdOrderByCreatedAtDesc(u.getId()));return "emergency/my-requests";}
 private boolean blank(String s){return s==null||s.isBlank();}private boolean digits(String s,int n){return s!=null&&s.matches("\\d{"+n+"}");}
}
